// Validate the ladder, then chart frontier growth: one-way vs bidirectional.
const L = nb.get('ladder');
if (!L) return 'Run the Clojure cell first.';

const dict = new Set(L.words);
const oneLetterApart = (a, b) =>
  a.length === b.length && [...a].filter((ch, i) => ch !== b[i]).length === 1;

let valid = L.ladder.every(w => dict.has(w));
for (let i = 1; i < L.ladder.length; i++) {
  if (!oneLetterApart(L.ladder[i - 1], L.ladder[i])) valid = false;
}
console.log('ladder:', L.ladder.join(' -> '));
console.log('every rung a real word, one letter apart:', valid);
console.log('explored - one-way:', L.onewayExpanded, ' bidirectional:', L.bidiExpanded,
  ' saving:', Math.round(100 * (1 - L.bidiExpanded / L.onewayExpanded)) + '%');

const rows = [];
L.oneway.forEach((s, i) => rows.push({ expansion: i + 1, size: s, strategy: 'one-way BFS' }));
L.bidi.forEach((s, i) => rows.push({ expansion: i + 1, size: s, strategy: 'bidirectional' }));

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 280,
  title: 'Frontier size per expansion round',
  data: { values: rows },
  mark: { type: 'line', point: true },
  encoding: {
    x: { field: 'expansion', type: 'quantitative', title: 'expansion round', axis: { tickMinStep: 1 } },
    y: { field: 'size', type: 'quantitative', title: 'frontier size (words)' },
    color: { field: 'strategy', type: 'nominal', title: null },
  },
};
